<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Register — DeploySift</title><link rel="icon" type="image/svg+xml" href="/favicon.svg"><style>body{margin:0;background:#0B1220;color:#eaf4ff;font:15px system-ui;display:flex;min-height:100vh;align-items:center;justify-content:center}.card{background:#151F30;border:1px solid #1e3450;border-radius:14px;padding:34px;width:100%;max-width:400px}.brand{font-weight:900;letter-spacing:2px;font-size:20px}.brand span{color:#22D3EE}.sub{color:#8aa0bb}label{display:block;margin:14px 0 5px;color:#9fc2e3}input{width:100%;padding:10px;background:#0B1220;color:#fff;border:1px solid #29445f;border-radius:7px;box-sizing:border-box}button{width:100%;padding:11px;margin-top:20px;border:0;border-radius:7px;background:#22D3EE;color:#0B1220;font-weight:700;cursor:pointer;font-size:15px}a{color:#818CF8;text-decoration:none}.err{color:#F87171;margin-top:12px;min-height:20px}.hint{color:#8aa0bb;font-size:13px}</style></head><body><div class="card"><div class="brand">DEPLOY<span>SIFT</span></div><p class="sub">Every clue. One diagnosis.</p><h1>Create account</h1><p class="hint">Every account gets a personal workspace automatically.</p><form id="f"><label for="name">Name</label><input id="name" required autocomplete="name"><label for="email">Email</label><input id="email" type="email" required autocomplete="email"><label for="p1">Password <span class="hint">(min 8 characters)</span></label><input id="p1" type="password" required autocomplete="new-password"><label for="p2">Confirm password</label><input id="p2" type="password" required autocomplete="new-password"><div class="err" id="err"></div><button type="submit">Register</button></form><p class="sub">Have an account? <a href="/login">Sign in</a> · <a href="/">Back to app</a></p></div><script>const csrf=document.querySelector('meta[name=csrf-token]').content;fetch('/api/me',{credentials:'same-origin',headers:{'Accept':'application/json'}}).then(r=>{if(r.ok)location.href='/';});document.querySelector('#f').addEventListener('submit',async v=>{v.preventDefault();let err=document.querySelector('#err');err.textContent='';let name=document.querySelector('#name').value,email=document.querySelector('#email').value,p1=document.querySelector('#p1').value,p2=document.querySelector('#p2').value;if(p1!==p2){err.textContent='Passwords do not match.';return;}let r=await fetch('/auth/register',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({name,email,password:p1,password_confirmation:p2})});if(r.ok)location.href='/';else{try{let j=await r.json();err.textContent=j.message||Object.values(j.errors||{})[0]?.[0]||'Registration failed.';}catch(e){err.textContent='Registration failed.';}}});</script></body></html>
